def helly_intervals(intervals):
    max_lower = max(a for a, _ in intervals)
    min_upper = min(b for _, b in intervals)
    if max_lower <= min_upper:
        return True, max_lower
    return False, None

def bellman_ford(n, constraints):
    dist = [0.0] * n
    for _ in range(n):
        for i, j, c in constraints:
            if dist[j] + c < dist[i]:
                dist[i] = dist[j] + c
    for i, j, c in constraints:
        if dist[j] + c < dist[i] - 1e-12:
            return False, None
    return True, [-d for d in dist]

def cycle_check(weights):
    if sum(weights) >= 0:
        sol = [0.0]
        s = 0.0
        for w in weights[:-1]:
            s += w
            sol.append(-s)
        return True, sol
    return False, None
